window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-174fb7297a0f704c"]={"versions": [{"id": "FIG-174fb7297a0f704c", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodell-Struktur des AUTOSAR Software Component Template (SWCT). Es definiert die grundlegenden Strukturbeziehungen zwischen Software-Komponententypen, Port-Prototypen und Port-Interfaces im Kontext der RTE-Spezifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ComponentType</code> (<code>ARElement</code>, Stereotyp <code>«atpType»</code>, <code>{abstract}</code>): Repräsentiert den Typ einer Software-Komponente; besitzt über eine gerichtete Komposition (<code>+component</code> zu <code>+port</code>, Multiplizität <code>0..*</code>) Port-Prototypen.</li>\n<li><code>PortPrototype</code> (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>, <code>{abstract}</code>): Abstrakte Basisklasse aller Port-Prototypen.</li>\n<li><code>RPortPrototype</code>: Konkrete Spezialisierung (Generalisierungsbeziehung auf <code>PortPrototype</code>) für Require-Ports; referenziert über die gerichtete Assoziation <code>+requiredInterface</code> (<code>«isOfType»</code>, Multiplizität Rolle <code>+rPort</code> <code>*</code>, Rolle <code>+requiredInterface</code> <code>1</code>) genau ein <code>PortInterface</code>.</li>\n<li><code>PPortPrototype</code>: Konkrete Spezialisierung (Generalisierungsbeziehung auf <code>PortPrototype</code>) für Provide-Ports; referenziert über die gerichtete Assoziation <code>+providedInterface</code> (<code>«isOfType»</code>, Multiplizität Rolle <code>+pPort</code> <code>*</code>, Rolle <code>+providedInterface</code> <code>1</code>) genau ein <code>PortInterface</code>.</li>\n<li><code>PortInterface</code> (<code>ARElement</code>, Stereotyp <code>«atpType»</code>, <code>{abstract}</code>): Abstraktes Kommunikationsinterface; enthält das Attribut <code>+ isService: Boolean</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamisches Laufzeit- oder Sequenzverhalten. Die Instanziierung und Zuordnung der Interfaces erfolgt statisch im Rahmen der Software-Architekturmodellierung vor der RTE-Generierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Metamodellvorgabe für AUTOSAR-Authoring-Tools und den RTE-Generator:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>ComponentType</code> kann beliebig viele (0 bis n) <code>PortPrototype</code>-Instanzen aggregieren.</li>\n<li>Jeder <code>RPortPrototype</code> muss exakt ein erforderliches <code>PortInterface</code> referenzieren (<code>requiredInterface</code>, Multiplizität 1).</li>\n<li>Jeder <code>PPortPrototype</code> muss exakt ein bereitgestelltes <code>PortInterface</code> referenzieren (<code>providedInterface</code>, Multiplizität 1).</li>\n<li>Ein einzelnes <code>PortInterface</code> kann von mehreren <code>RPortPrototype</code>- bzw. <code>PPortPrototype</code>-Elementen typisiert werden (<code>*</code>).</li>\n<li>Das Flag <code>isService</code> deklariert, ob ein Interface für Standard-/Basis-Software-Dienste (Service-Ports) verwendet wird.</li>\n</ul>"}, {"id": "FIG-e967d21c5f3bb1de", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodell-Struktur des AUTOSAR Software Component Template (SWCT). Es definiert die grundlegenden Strukturbeziehungen zwischen Software-Komponententypen, Port-Prototypen und Port-Interfaces im Kontext der RTE-Spezifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ComponentType</code> (<code>ARElement</code>, Stereotyp <code>«atpType»</code>): Repräsentiert den Typ einer Software-Komponente; besitzt über eine gerichtete Komposition (<code>+component</code> zu <code>+port</code>, Multiplizität <code>0..*</code>) Port-Prototypen.</li>\n<li><code>PortPrototype</code> (<code>Identifiable</code>, Stereotyp <code>«atpPrototype»</code>): Basisklasse aller Port-Prototypen.</li>\n<li><code>RPortPrototype</code> (Stereotyp <code>«atpPrototype»</code>): Spezialisierung (Generalisierungsbeziehung auf <code>PortPrototype</code>) für Require-Ports; referenziert über die gerichtete Assoziation <code>+requiredInterface</code> (<code>«isOfType»</code>, Multiplizität Rolle <code>+rPort</code> <code>*</code>, Rolle <code>+requiredInterface</code> <code>1</code>) genau ein <code>PortInterface</code>.</li>\n<li><code>PPortPrototype</code> (Stereotyp <code>«atpPrototype»</code>): Spezialisierung (Generalisierungsbeziehung auf <code>PortPrototype</code>) für Provide-Ports; referenziert über die gerichtete Assoziation <code>+providedInterface</code> (<code>«isOfType»</code>, Multiplizität Rolle <code>+pPort</code> <code>*</code>, Rolle <code>+providedInterface</code> <code>1</code>) genau ein <code>PortInterface</code>.</li>\n<li><code>PortInterface</code> (<code>ARElement</code>, Stereotyp <code>«atpType»</code>): Kommunikationsinterface; enthält das hervorgehobene Attribut <code>+ isService :Boolean</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Definition ohne dynamisches Laufzeit- oder Sequenzverhalten. Die Instanziierung und Zuordnung der Interfaces erfolgt statisch im Rahmen der Software-Architekturmodellierung vor der RTE-Generierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Metamodellvorgabe für AUTOSAR-Authoring-Tools und den RTE-Generator:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>ComponentType</code> kann beliebig viele (0 bis n) <code>PortPrototype</code>-Instanzen aggregieren.</li>\n<li>Jeder <code>RPortPrototype</code> muss exakt ein erforderliches <code>PortInterface</code> referenzieren (<code>requiredInterface</code>, Multiplizität 1).</li>\n<li>Jeder <code>PPortPrototype</code> muss exakt ein bereitgestelltes <code>PortInterface</code> referenzieren (<code>providedInterface</code>, Multiplizität 1).</li>\n<li>Ein einzelnes <code>PortInterface</code> kann von mehreren <code>RPortPrototype</code>- bzw. <code>PPortPrototype</code>-Elementen typisiert werden (<code>*</code>).</li>\n<li>Das Flag <code>isService</code> deklariert, ob ein Interface für Standard-/Basis-Software-Dienste (Service-Ports) verwendet wird.</li>\n</ul>"}], "trans": [{"from": "FIG-174fb7297a0f704c", "to": "FIG-e967d21c5f3bb1de", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Farbschema der Klassenkästen von Grau/Weiß auf Beige/Pastellgelb geändert.</li>\n<li>Klassen <code>ComponentType</code>, <code>PortPrototype</code> und <code>PortInterface</code>: Eigenschaftsmodifikator <code>{abstract}</code> entfernt.</li>\n<li>Klassen <code>RPortPrototype</code> und <code>PPortPrototype</code>: Stereotyp <code>«atpPrototype»</code> ergänzt.</li>\n<li>Klasse <code>PortInterface</code>: Attributbeschriftung <code>+ isService :Boolean</code> in roter Schrift hervorgehoben.</li>\n</ul>"}]};
